// Decides whether each Shopify product should become a pin now.
// Missing settings stop the run with a clear message. Products that are not
// ready yet (draft, hidden, no photo) get a skip_reason and are dropped by the
// next node; the "product updated" trigger pins them once they are ready.

const settings = $input.first().json;
const accountId = String(settings.pinterest_account_id || '').trim();
const boardId = String(settings.pinterest_board_id || '').trim();
const storeUrl = String(settings.shopify_store_url || '').trim().replace(/\/+$/, '');
const currency = String(settings.store_currency || '').trim().toUpperCase();

const missing = [];
if (!accountId || accountId.includes('PASTE_')) missing.push('your PinBridge account ID');
if (!boardId || boardId.includes('PASTE_')) missing.push('your Pinterest board ID');
if (!/^https?:\/\/[^\s/]+\.[^\s/]+(\/\S*)?$/i.test(storeUrl) || storeUrl.includes('your-store')) {
  missing.push('your store URL, such as https://shop.example.com');
}
if (currency && !/^[A-Z]{3}$/.test(currency)) {
  missing.push('your store currency as a 3-letter code such as USD or EUR (or leave it empty)');
}
if (missing.length) {
  throw new Error(`Fill in ${missing.join(', ')} in "Configure your Pinterest settings".`);
}

// The featured photo: Shopify sends it as `image`, and first in `images`.
function mainPhoto(p) {
  const images = Array.isArray(p.images)
    ? [...p.images].sort((a, b) => (a.position || 0) - (b.position || 0))
    : [];
  const photo = (p.image && p.image.src ? p.image : images[0]) || {};
  let src = String(photo.src || '').trim();
  if (src.startsWith('//')) src = `https:${src}`;
  return { src, alt: String(photo.alt || '').trim() };
}

// Products already pinned by this workflow (saved by "Remember the pinned product").
const pinned = $getWorkflowStaticData('global').pinnedProducts || {};
const now = Date.now();

return $input.all().map(({ json: p }, itemIndex) => {
  const photo = mainPhoto(p);
  let skip_reason = '';

  if (p.status && p.status !== 'active') {
    skip_reason = `Product is ${p.status}, not active.`;
  } else if (!p.published_at) {
    // Online Store publication. For a headless store, remove this check.
    skip_reason = 'Product is not published to the Online Store.';
  } else if (Date.parse(p.published_at) > now) {
    skip_reason = 'Product is scheduled to publish later.';
  } else if (!photo.src) {
    skip_reason = 'Product has no photo yet.';
  } else if (!p.handle) {
    skip_reason = 'Product has no URL handle.';
  } else if (pinned[String(p.id)]) {
    skip_reason = 'Product is already on Pinterest.';
  }

  return {
    json: {
      ...p,
      pinterest_account_id: accountId,
      pinterest_board_id: boardId,
      shopify_store_url: storeUrl,
      store_currency: currency,
      image_url: photo.src,
      image_alt: photo.alt,
      skip_reason
    },
    pairedItem: { item: itemIndex }
  };
});

// Turns a Shopify product into Pinterest-ready copy.
// Rewrite the description lines at the bottom to match your brand voice.

const ENTITIES = {
  amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ',
  lsquo: '‘', rsquo: '’', ldquo: '“', rdquo: '”',
  ndash: '–', mdash: '—', hellip: '…', bull: '•', middot: '·',
  trade: '™', reg: '®', copy: '©', deg: '°', times: '×',
  euro: '€', pound: '£', yen: '¥', cent: '¢'
};

const decodeEntities = (text) => text.replace(/&(#x[0-9a-f]+|#\d+|[a-z]+);/gi, (match, code) => {
  if (code[0] !== '#') return ENTITIES[code] ?? ENTITIES[code.toLowerCase()] ?? match;
  const point = code[1] === 'x' || code[1] === 'X'
    ? parseInt(code.slice(2), 16)
    : parseInt(code.slice(1), 10);
  try { return String.fromCodePoint(point); } catch (error) { return ''; }
});

// Titles and product types: plain text, entities decoded, no stray tags.
const toPlain = (text) => decodeEntities(String(text || '').replace(/<[^>]*>/g, ''))
  .replace(/\s+/g, ' ')
  .trim();

// Product descriptions are HTML: drop scripts and styles, keep the words, and
// end each paragraph or list item as its own sentence.
const toSentences = (html) => decodeEntities(String(html || '')
  .replace(/<(script|style)\b[\s\S]*?<\/\1>/gi, ' ')
  .replace(/<\/?(p|div|br|li|ul|ol|h[1-6]|tr|td|th|table|section|blockquote)\b[^>]*>/gi, '\n')
  .replace(/<[^>]*>/g, ''))
  .split('\n')
  .map((line) => line.replace(/\s+/g, ' ').trim())
  .filter(Boolean)
  .map((line) => (/[.!?:;…]$/.test(line) ? line : `${line}.`))
  .join(' ');

// Shortens text at a word boundary so pins never end mid-word.
const clip = (text, max) => {
  if (text.length <= max) return text;
  const cut = text.slice(0, max - 1);
  const space = cut.lastIndexOf(' ');
  return `${(space > max * 0.6 ? cut.slice(0, space) : cut).replace(/[\s,.;:!?\-]+$/, '')}…`;
};

function priceLine(p) {
  const currency = p.store_currency;
  const prices = (p.variants || [])
    .map((variant) => Number.parseFloat(variant.price))
    .filter((price) => Number.isFinite(price) && price > 0);
  if (!currency || !prices.length) return '';

  const low = Math.min(...prices);
  const high = Math.max(...prices);
  let amount;
  try {
    amount = new Intl.NumberFormat('en-US', { style: 'currency', currency }).format(low);
  } catch (error) {
    amount = `${currency} ${low.toFixed(2)}`;
  }
  return low === high ? `Available now for ${amount}.` : `Available now from ${amount}.`;
}

return $input.all().map(({ json: p }, itemIndex) => {
  const title = clip(toPlain(p.title), 100);
  const summary = clip(toSentences(p.body_html), 380) || toSentences(title);
  const altText = toPlain(p.image_alt) || [title, toPlain(p.product_type)].filter(Boolean).join(', ');

  return {
    json: {
      pinterest_account_id: p.pinterest_account_id,
      pinterest_board_id: p.pinterest_board_id,
      product_id: p.id,
      title,
      description: clip([summary, priceLine(p)].filter(Boolean).join('\n\n'), 500),
      link_url: `${p.shopify_store_url}/products/${encodeURIComponent(p.handle)}`,
      image_url: p.image_url,
      alt_text: clip(altText, 500)
    },
    pairedItem: { item: itemIndex }
  };
});

// The photo was downloaded and uploaded one-for-one, so item {i} here is still
// item {i} of "Build the pin title and description". Merging by index rather
// than by paired items keeps this working after the Filter has dropped rows.
const rows = $('Build the pin title and description').all();

return $input.all().map((item, i) => {
  if (!item.json.id) {
    throw new Error(`PinBridge returned no asset ID for "${rows[i].json.title}".`);
  }
  return {
    json: { ...rows[i].json, asset_id: item.json.id },
    pairedItem: { item: i }
  };
});

// Remember which products are on Pinterest, so later edits to the same product
// skip the download and upload. The idempotency key already stops a second pin;
// this only saves the work. n8n keeps this list for active (production) runs,
// not for test runs from the editor.
const saved = $getWorkflowStaticData('global');
saved.pinnedProducts = saved.pinnedProducts || {};
const rows = $('Attach the uploaded asset ID').all();

return $input.all().map((item, i) => {
  saved.pinnedProducts[String(rows[i].json.product_id)] = item.json.id || true;
  return { json: item.json, pairedItem: { item: i } };
});

// Stops the run while the confirmation settings still hold placeholders.
// A placeholder secret is public text, so anyone who has read this template
// could sign a fake "pin is live" request with it. It is never accepted.
const cfg = $input.first().json;
const secret = String(cfg.pinbridge_webhook_secret || '').trim();
const chatId = String(cfg.telegram_chat_id || '').trim();

const missing = [];
if (secret.length < 16 || secret.includes('PASTE_')) missing.push('a signing secret of 16 or more characters');
if (!chatId || chatId.includes('PASTE_')) missing.push('your Telegram chat ID');
if (missing.length) {
  throw new Error(`Fill in ${missing.join(' and ')} in "Configure the confirmation step".`);
}

return $input.all();

// Only pins this workflow created get a message. Pins it publishes directly
// carry a "shopify-" idempotency key. If you switched "Publish the pin to
// Pinterest" to the Schedule resource, PinBridge keys each pin
// "schedule_<schedule ID>" when its schedule fires, so it is matched against
// the schedule IDs saved by "Remember the pinned product".
const pin = $input.first().json;
const hook = $('Configure the confirmation step').first().json;
const event = hook.headers['x-pinbridge-event'];
const key = String(pin.idempotencyKey || '');
const remembered = new Set(
  Object.values($getWorkflowStaticData('global').pinnedProducts || {}).map(String)
);

const fromThisWorkflow = key.startsWith('shopify-') ||
  (key.startsWith('schedule_') && remembered.has(key.slice('schedule_'.length)));
if (!fromThisWorkflow) {
  return [];
}

const title = pin.title || 'Untitled pin';
const product = pin.linkUrl ? `\nProduct: ${pin.linkUrl}` : '';
let text;

if (event === 'pin.published') {
  const live = pin.pinterestPinId ? `\nhttps://www.pinterest.com/pin/${pin.pinterestPinId}/` : '';
  text = `Live on Pinterest: ${title}${live}${product}`;
} else {
  const reason = hook.body.error_message || pin.errorMessage || hook.body.error_code || 'no reason given';
  text = `Pinterest did not publish "${title}": ${reason}${product}`;
}

return [{
  json: { event, pin_id: pin.id, title, text, chat_id: hook.telegram_chat_id },
  pairedItem: { item: 0 }
}];
